<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../api/client'
import { money, shortDate, shortTime } from '../format'
const route=useRoute(); const activity=ref<any>(); const participants=ref<any[]>([]); const candidates=ref<any>({candidates:[],other_windows:[]}); const bookings=ref<any[]>([]); const tab=ref('arrange'); const error=ref(''); const saved=ref(''); const courtId=ref('1号场'); const orderNo=ref(''); const paid=ref(''); let events:EventSource|undefined
const id=String(route.params.id); const me=computed(()=>participants.value.find(p=>p.id===activity.value?.my_participant_id))
onMounted(async()=>{await load();events=new EventSource(`/api/v1/events?watch_activity_id=${id}`);events.addEventListener('resource.changed',()=>window.setTimeout(load,150))}); onBeforeUnmount(()=>events?.close())
async function load(){try{activity.value=await api(`/activities/${id}`);const [p,c,b]=await Promise.all([api<any>(`/activities/${id}/participants`),api<any>(`/activities/${id}/candidates`),api<any>(`/activities/${id}/bookings`)]);participants.value=p.items;candidates.value=c;bookings.value=b.items}catch(e){error.value=e instanceof Error?e.message:'无法读取活动'}}
async function share(){const data=await api<any>(`/activities/${id}/invite`);const url=`${location.origin}${data.url}`;if(navigator.share)await navigator.share({title:activity.value.title,text:`来参加 ${activity.value.title}`,url});else await navigator.clipboard.writeText(url);saved.value='邀请链接已复制';setTimeout(()=>saved.value='',1600)}
async function choose(c:any){await api(`/activities/${id}/plans`,{method:'POST',body:JSON.stringify({candidate_id:c.id,roster_participant_ids:c.eligible_participant_ids.slice(0,activity.value.max_players),expected_version:activity.value.version})});await load()}
async function rsvp(response:string){await api(`/activities/${id}/rsvp`,{method:'PUT',body:JSON.stringify({plan_id:activity.value.current_plan_id,response})});await load()}
async function attendance(state:string){await api(`/activities/${id}/attendance`,{method:'PUT',body:JSON.stringify({entries:[{participant_id:activity.value.my_participant_id,state}],verify:false})});await load()}
async function finish(){await api(`/activities/${id}/finish`,{method:'POST',body:JSON.stringify({expected_version:activity.value.version})});await load()}
async function recordBooking(){error.value='';try{const plan=activity.value.current_plan;const booking=await api<any>(`/activities/${id}/bookings`,{method:'POST',body:JSON.stringify({venue_id:plan.venue_id,court_ids:[courtId.value],starts_at:plan.starts_at,ends_at:plan.ends_at,external_order_no:orderNo.value||null,booker_participant_id:activity.value.my_participant_id,quoted_total_cents:null,note:null,expected_version:activity.value.version})});if(paid.value)await api(`/activities/${id}/bookings/${booking.id}/payment`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({amount_cents:Math.round(Number(paid.value)*100),payer_participant_id:activity.value.my_participant_id})});await load()}catch(e){error.value=e instanceof Error?e.message:'登记失败'}}
async function verify(person:any,state:string){await api(`/activities/${id}/attendance`,{method:'PUT',body:JSON.stringify({entries:[{participant_id:person.id,state}],verify:true})});await load()}
async function cancelActivity(){const reason=window.prompt('请填写取消原因');if(!reason)return;await api(`/activities/${id}/cancel`,{method:'POST',body:JSON.stringify({reason,expected_version:activity.value.version})});await load()}
</script>
<template><section class="shell page"><div v-if="activity" class="stack"><div class="page-head"><div><span class="badge">{{ activity.status_label }}</span><h1>{{ activity.title }}</h1><p class="muted">{{ activity.date_from }} 至 {{ activity.date_to }} · {{ activity.duration_minutes }} 分钟</p></div><button @click="share">{{ saved||'分享邀请' }}</button></div><nav class="tabs"><button :class="{active:tab==='arrange'}" @click="tab='arrange'">安排</button><button :class="{active:tab==='members'}" @click="tab='members'">成员</button><RouterLink :to="`/a/${activity.id}/bill`">费用</RouterLink></nav><div class="activity-layout"><div class="stack"><template v-if="tab==='arrange'"><article v-if="activity.status==='collecting'" class="card stack"><div><p class="eyebrow">推荐方案</p><h2 v-if="candidates.candidates.length">{{ candidates.candidates.length }} 个方案满足条件</h2><h2 v-else>等待空闲时间与场地相遇</h2></div><div v-for="candidate in candidates.candidates.slice(0,3)" :key="candidate.id" class="candidate"><div><p class="candidate-time">{{ shortDate(candidate.starts_at) }} {{ shortTime(candidate.starts_at) }}–{{ shortTime(candidate.ends_at) }}</p><p><strong>{{ candidate.eligible_participant_ids.length }} 人可来</strong> · {{ candidate.venue_name }}</p><p class="muted">{{ candidate.continuous_court_count }} 块连续可用 · {{ money(candidate.total_price_cents) }}</p></div><button v-if="activity.is_host" class="primary" @click="choose(candidate)">选择这个方案</button></div><RouterLink v-if="!candidates.candidates.length" class="button primary" :to="`/me/time?activity_id=${id}`">填写我的时间</RouterLink><details v-if="candidates.other_windows.length"><summary>其他时间（{{candidates.other_windows.length}}）</summary><p v-for="other in candidates.other_windows.slice(0,5)" :key="other.id" class="muted">{{shortDate(other.starts_at)}} {{shortTime(other.starts_at)}} · {{other.classification}}</p></details></article><article v-else class="card result-card stack"><p class="eyebrow">{{ activity.status==='booking'?'方案已选，等待订场':activity.status==='confirmed'?'场地已确定':activity.status==='finished'?'本场已结束':'本场已取消' }}</p><h2 v-if="activity.current_plan">{{shortDate(activity.current_plan.starts_at)}} {{shortTime(activity.current_plan.starts_at)}}–{{shortTime(activity.current_plan.ends_at)}}</h2><p v-if="bookings.length">{{bookings[0].court_ids.join('、')}} · 已付 {{money(bookings.reduce((n,b)=>n+b.paid_total_cents,0))}}</p><p v-else class="muted">主持人需要按选定方案去场馆网站预约，再回来登记订单。</p><form v-if="activity.is_host&&activity.status==='booking'" class="booking-form" @submit.prevent="recordBooking"><label>实际球场<input v-model="courtId" required></label><label>订单号（可选）<input v-model="orderNo"></label><label>本次已支付（元，可选）<input v-model="paid" inputmode="decimal"></label><button class="primary" type="submit">登记已订场</button></form><div v-if="me?.rsvp_plan_id" class="actions"><button :class="{primary:me.rsvp==='yes'}" @click="rsvp('yes')">参加</button><button @click="rsvp('no')">不参加</button></div><div v-if="activity.status==='confirmed'" class="actions"><button @click="attendance('present')">我已到场</button><button @click="attendance('absent')">我缺席</button><button v-if="activity.is_host" class="primary" @click="finish">结束并核对到场</button></div></article></template><article v-else class="card"><h2>成员与到场</h2><div v-for="person in participants" :key="person.id" class="person"><span class="avatar">{{person.display_name.slice(0,1)}}</span><div><strong>{{person.display_name}}</strong><p>{{person.required?'核心成员 · ':''}}{{person.rsvp==='yes'?'已参加':person.rsvp==='no'?'不参加':'待回应'}} · {{person.attendance==='present'?'到场':person.attendance==='absent'?'缺席':'待核对'}}{{person.attendance_verified?'（已核对）':''}}</p></div><div v-if="activity.is_host&&(activity.status==='finished'||activity.status==='cancelled')" class="verify"><button @click="verify(person,'present')">到场</button><button @click="verify(person,'absent')">缺席</button></div></div></article><p v-if="error" class="error">{{error}}</p></div><aside class="card stack"><div><h2>这场球的进度</h2><p><strong>{{ activity.participant_count }}</strong> 人已加入 · 计划 {{activity.min_players}}–{{activity.max_players}} 人</p><p class="muted">活动短号 {{ activity.short_code }}</p></div><RouterLink class="button" :to="`/me/time?activity_id=${id}`">修改本次时间</RouterLink><button v-if="activity.is_host&&['collecting','booking','confirmed'].includes(activity.status)" @click="cancelActivity">取消这场活动</button></aside></div><div class="mobile-action"><RouterLink v-if="activity.status==='finished'||activity.status==='cancelled'" class="button primary" :to="`/a/${id}/bill`">处理本场账单</RouterLink><RouterLink v-else class="button primary" :to="`/me/time?activity_id=${id}`">填写我的时间</RouterLink></div></div><p v-else-if="error" class="error">{{ error }}</p></section></template>
<style scoped>.tabs{display:flex;gap:8px;border-bottom:1px solid var(--line);margin-bottom:20px}.tabs button,.tabs a{min-height:44px;border:0;background:transparent;color:var(--muted);text-decoration:none;padding:12px}.tabs .active{color:var(--primary);border-bottom:2px solid var(--primary)}.activity-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:20px}.candidate{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 0;border-top:1px solid var(--line)}.candidate-time{font-size:22px;line-height:1.35;font-weight:750;margin-bottom:6px}.candidate p{margin-bottom:4px}.person{display:flex;gap:12px;align-items:center;padding:12px 0;border-top:1px solid var(--line)}.person>div:nth-child(2){flex:1}.person p{font-size:13px;color:var(--muted);margin:3px 0}.avatar{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:var(--primary-soft);color:var(--primary);font-weight:700}.actions,.verify{display:flex;flex-wrap:wrap;gap:8px}.verify button{min-height:36px;padding:0 10px}.booking-form{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding-top:16px;border-top:1px solid var(--line)}.booking-form button{align-self:end}@media(max-width:720px){.activity-layout,.booking-form{grid-template-columns:1fr}.activity-layout aside{order:-1}.candidate{align-items:flex-start;flex-direction:column}.candidate button{width:100%}.person{align-items:flex-start;flex-wrap:wrap}.verify{width:100%;padding-left:52px}}</style>
